import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';
import {journalLines} from '../live-paper/journal-lines.mjs';import {sealedNativePrefix} from '../live-paper/native-dip-host-v1.mjs';
import {engineBookPointsV1} from '../paper/maker-engine-book-point-v1.mjs';import {createMicropriceCalibrationV1} from '../research/microprice-edge-calibration-v1.mjs';
const rt=path.join(process.env.LOCALAPPDATA,'SigTradingCup/paper-runtime'),session=JSON.parse(fs.readFileSync(path.join(rt,'realtime-session.json')));if(!/^realtime-[A-Za-z0-9.-]+\.jsonl$/.test(session.file))throw Error('CALIBRATION_SOURCE_PATH');
const file=path.join(rt,session.file),seal=sealedNativePrefix(file),through=new Date().toISOString(),splitAt=new Date(Date.parse(session.startedAt)+.7*(Date.parse(through)-Date.parse(session.startedAt))).toISOString(),scope={tournamentId:session.scope.tournamentId,exchanges:session.scope.markets},study=createMicropriceCalibrationV1({splitAt}),prefix=createHash('sha256'),sampled=new Map(),revisions=new Map();let index=0,accepted=0,rejected=0;const started=performance.now();
for(const line of journalLines(file,{endByte:seal.bytes})){prefix.update(line+'\n');const r=JSON.parse(line);if(r.format!=='sig-feed-capture'||r.captureIndex!==index++)throw Error('CALIBRATION_CAPTURE_CHAIN');if(r.kind!=='event'||r.event!=='market_batch')continue;const key=r.topic+':'+r.epoch,rev=r.payload?.delivery?.revision;if(!Number.isSafeInteger(rev)||rev<=(revisions.get(key)??-1))continue;revisions.set(key,rev);const at=Date.parse(r.observedAt);if(at-(sampled.get(key)??-Infinity)<1000)continue;sampled.set(key,at);const result=engineBookPointsV1(r,scope,r.observedAt);rejected+=result.rejected.length;for(const b of result.books){study.observe(b,r.observedAt);accepted++;}}
const current=fs.statSync(file);if(current.dev!==seal.dev||current.ino!==seal.ino||current.size<seal.bytes)throw Error('CALIBRATION_SOURCE_REPLACED');const report={at:new Date().toISOString(),source:{file:session.file,bytes:seal.bytes,sha256:prefix.digest('hex'),captureRecords:index,from:session.startedAt,through},timingMs:performance.now()-started,acceptedPoints:accepted,rejectedPoints:rejected,...study.report(),limitations:['Capture replay tests predictive markout only; it does not prove maker fills, queue position, or executable profit.','The one-spread hurdle is a descriptive friction proxy; fees are zero per challenge assumption.','Only a single chronological split is reported; bins qualify for review at 100 labels across 5 markets.'],networkRequests:0,contestOrders:0};fs.writeFileSync('data/microprice-edge-calibration-20261013.json',JSON.stringify(report));console.log(JSON.stringify({source:report.source,timingMs:report.timingMs,diagnostics:report.diagnostics,heldout:report.groups.filter(x=>x.period==='heldout').length,qualifying:report.groups.filter(x=>x.period==='heldout'&&x.qualifiesForReview).map(({horizonMs,features,samples,markets,meanAfterOneSpreadTicks,afterSpreadPositiveRate})=>({horizonMs,features,samples,markets,meanAfterOneSpreadTicks,afterSpreadPositiveRate}))}));
